import{_ as i,C as n,o as l,c as m,a2 as e,j as t,a as o,E as s}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"KomaYomi（格读）— ローカル優先の漫画精読ツール","titleTemplate":false,"description":"KomaYomi（格读）ドキュメント — ローカル優先、コマ単位の漫画精読ツール。日・中・英を並べて読み、ノートと注釈を絵に貼り、学習ページとして書き出せます。ファイルは手元に残ります。","frontmatter":{"layout":"home","titleTemplate":false,"description":"KomaYomi（格读）ドキュメント — ローカル優先、コマ単位の漫画精読ツール。日・中・英を並べて読み、ノートと注釈を絵に貼り、学習ページとして書き出せます。ファイルは手元に残ります。","title":"KomaYomi（格读）— ローカル優先の漫画精読ツール","hero":{"name":"KomaYomi（格读）","text":"漫画をコマ単位で精読する","tagline":"同じページを日・中・英で。ノートと注釈は絵に貼ったまま。ローカル優先、アカウント不要。","image":{"src":"/assets/screenshots/hero-real-library.webp","alt":"実際のライブラリを使った3言語の比較リーダー。漫画の絵はぼかし処理済み"},"actions":[{"theme":"brand","text":"はじめる","link":"/ja/guide/introduction"},{"theme":"alt","text":"データ形式","link":"/ja/data-format"}]},"features":[{"title":"まずコマから","details":"XYカットによる自動検出に加え、手描き、結合、番号付け、再利用できるレイアウトテンプレート。再検出やテンプレート適用のときも、ノートと注釈は絵に合わせて再マッピングされ、失われません。"},{"title":"複数言語を比較","details":"並べて表示または重ね表示、言語ごとのマスク、ホイールズームとパン、さらにページ／コマ／アンカー／グリッドの位置合わせと再利用できるプリセット。"},{"title":"絵に貼るノート","details":"ページ単位・コマ単位の Markdown ノートを種類別の色付きカードで表示。絵の一点にピン留めでき、タグ、出典、スクラッチパッド、全文検索、LLM に貼るためのワンクリック「コンテキストをコピー」も使えます。"},{"title":"持ち出せる出力","details":"画像フォルダ付きの HTML または単一の埋め込みファイルとしてエクスポートし、ページ／コマ／コラージュの PNG と共有画像を書き出し、すべてを `.mnproj` プロジェクトとして移せます。"}]},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md","lastUpdated":1794842245000}'),d={name:"ja/index.md"};function p(c,a,h,g,u,f){const r=n("Badge");return l(),m("div",null,[a[4]||(a[4]=e('<h2 id="なぜ-komayomi-なのか" tabindex="-1">なぜ KomaYomi なのか <a class="header-anchor" href="#なぜ-komayomi-なのか" aria-label="Permalink to &quot;なぜ KomaYomi なのか&quot;">​</a></h2><p>漫画を外国語で読むとき、たいてい窓が三つ必要です。原作、翻訳、辞書。さらにノートアプリを開き、書きたい一文の位置はだいたいずれています。KomaYomi（格读）は、同じページの日本語・中国語・英語を一つの窓に並べ、まずコマに分け、Markdown ノートと注釈を絵のその場所に貼れるようにします。作業の単位はページではなくコマです。</p><p>ローカル Web アプリなので、ページ画像は <code>raw/</code> フォルダのまま、コマ、ノート、タグ、注釈は <code>data/</code> 以下のプレーンな JSON に保存されます。エクスポートしない限り、データがマシンの外に出ることはありません。スキャンは自分で用意してください。学習用のツールであり、漫画の配布サービスではありません。</p><p>作者ページ：<a href="https://x.com/payayakamo" target="_blank" rel="noopener noreferrer">X · @payayakamo</a> · <a href="https://note.com/payayakamo" target="_blank" rel="noopener noreferrer">note · @payayakamo</a>。どちらも作者個人のページで、製品サイトではありません。</p><h2 id="_3-手順ではじめる" tabindex="-1">3 手順ではじめる <a class="header-anchor" href="#_3-手順ではじめる" aria-label="Permalink to &quot;3 手順ではじめる&quot;">​</a></h2><ol><li><strong>入れる、または走らせる</strong>：<a href="https://github.com/PayayaKamo/KomaYomi/releases" target="_blank" rel="noopener noreferrer">GitHub Releases</a> からビルドを入手。または <code>npm install &amp;&amp; npm run dev</code> で <code>http://127.0.0.1:5173</code> を開く。</li><li><strong>ページを置く</strong>：<code>raw/&lt;巻&gt;/&lt;言語&gt;/&lt;話&gt;/001.jpg</code> に置くか、「ファイル → ライブラリフォルダーを開く…」を使う。</li><li><strong>話を開く</strong>：初回はコマが自動検出される（下書きとして扱う）。比較リーダーで読み、ノートを書き、書き出す。</li></ol><p>インストール方法の詳細、初回のフォルダー構成、コマの修正は<a href="/KomaYomi-docs/ja/guide/installation">インストールと起動</a>と<a href="/KomaYomi-docs/ja/guide/introduction">はじめに</a>にあります。</p><h2 id="現状の概要" tabindex="-1">現状の概要 <a class="header-anchor" href="#現状の概要" aria-label="Permalink to &quot;現状の概要&quot;">​</a></h2><p>KomaYomi（格读）は <strong>1.1.0</strong> です。このドキュメントでは、現在存在する機能と計画中の機能を区別して説明します。</p><div class="status-list"><div><strong>読む</strong> — 複数作品のルートを含むライブラリのスキャン、サイドバーのページ一覧 3 表示、コマ検出と手動編集、分割と番号の並べ替え、レイアウトテンプレート、言語別マスク付きの比較リーダー、原版ビュー、1:1 の拡大ビュー、ページ・話をまたぐ前後のコマと自動センタリング、集中モードと読み取り専用モード。</div><div><strong>ノートと注釈</strong> — ページ／コマ単位の Markdown ノート、種類付きノート（背景知識・単語・つぶやき、有効な言語ごとに1種類、色を選べるカスタム種類）、絵に貼るピンと件数付きポップオーバー、ノート検索、単一エディター、アンカーと引き出し線付きで言語ごとに分かれたベクター注釈と右クリックメニュー、Undo スタックと連動する操作履歴。</div><div><strong>プロジェクトと出力</strong> — 開いた `.mnproj` へ書き戻す保存、デスクトップ版の「名前を付けて保存…」（ブラウザーではダウンロードにフォールバック）、注釈を既定で焼き込む HTML / PNG / PDF（印刷）/ Word エクスポート、Xiaohongshu（RED）向け共有画像、バックアップ ZIP と定期バックアップ、キャッシュ管理、オフライン書き込みキュー付き WebDAV ソース、スキーマ検証付きのアトミック保存と `.bak` ローテーション・同時書き込みロック、CLI バッチツール。</div><div><strong>計画中</strong> — 語彙リストのエクスポート。アプリ内での画像形式変換（名前変更と分割は前処理にあります）。より広範な統合テスト。</div></div>',10)),t("p",null,[a[0]||(a[0]=o("このサイトで ",-1)),s(r,{type:"warning",text:"予定"}),a[1]||(a[1]=o(" と表示されているものは",-1)),a[2]||(a[2]=t("strong",null,"まだ実装されていません",-1)),a[3]||(a[3]=o("。コードにない挙動をページが説明している場合は、この注記を優先し、その機能は利用できないものと考えてください。",-1))]),a[5]||(a[5]=e('<h2 id="komayomi-の-4-つのリポジトリ" tabindex="-1">KomaYomi の 4 つのリポジトリ <a class="header-anchor" href="#komayomi-の-4-つのリポジトリ" aria-label="Permalink to &quot;KomaYomi の 4 つのリポジトリ&quot;">​</a></h2><p>このサイトが扱うのはデスクトップ完全版です。同じプロジェクトには他に 3 つの形態があります。</p><ul><li><a href="https://github.com/PayayaKamo/KomaYomi" target="_blank" rel="noopener noreferrer">KomaYomi</a> — デスクトップ完全版（Electron とローカルサーバー）。このドキュメントの対象です。</li><li><a href="https://github.com/PayayaKamo/KomaYomi-online" target="_blank" rel="noopener noreferrer">KomaYomi-online</a> — ブラウザー専用版。<code>.mnproj</code> プロジェクトを開いて閲覧・注釈・エクスポートができ、サーバーは不要です。</li><li><a href="https://github.com/PayayaKamo/KomaYomi-mobile" target="_blank" rel="noopener noreferrer">KomaYomi-mobile</a> — Android / iOS 向けの React Native アプリ。HarmonyOS NEXT は現在プレースホルダーのみです。</li><li><a href="https://github.com/PayayaKamo/KomaYomi-docs" target="_blank" rel="noopener noreferrer">KomaYomi-docs</a> — このサイトのビルド成果物で、CI が push します。ドキュメントの編集はメインリポジトリで行ってください。</li></ul><p>各形態は同じページ JSON と <code>.mnproj</code> 形式を共有しており、作業内容は形態間で移せます。</p><h2 id="次に読む" tabindex="-1">次に読む <a class="header-anchor" href="#次に読む" aria-label="Permalink to &quot;次に読む&quot;">​</a></h2><ul><li>はじめてですか？ <a href="/KomaYomi-docs/ja/guide/introduction">はじめに</a> を読んでから <a href="/KomaYomi-docs/ja/guide/installation">インストールと起動</a> へ。</li><li>全体像を知りたい？ <a href="/KomaYomi-docs/ja/concepts">基本概念</a> から始めてください。</li><li>JSON を扱う、プラグインを書く？ <a href="/KomaYomi-docs/ja/data-format">データ形式</a> と <a href="/KomaYomi-docs/ja/extending">レイアウトテンプレートとプラグイン</a> へ。</li><li>ページが見つからない、エクスポートが壊れた？ <a href="/KomaYomi-docs/ja/faq">FAQ とトラブルシューティング</a> を見てください。</li></ul><div class="tip custom-block"><p class="custom-block-title">ドキュメントの言語</p><p>英語が主要な言語です。中国語訳は <code>/zh/</code>、日本語訳は <code>/ja/</code> にあります。各ページはそれぞれの状態を個別に示します。</p></div>',7))])}const K=i(d,[["render",p]]);export{b as __pageData,K as default};
